import pandas as pd

customers = pd.DataFrame({
    "name": ["王大明", "李小華"],
    "email": ["daming@example.com", "xiaohua@example.com"],
    "phone": ["0912345678", "0922333444"],
    "birth_year": [1988, 1992],
    "city": ["台北市", "台北市"],
    "occupation": ["工程師", "行銷專員"],
    "monthly_spend": [12000, 8500],
    "health_flag": [0, 0]
})

direct_identifiers = {"name", "email", "phone"}
quasi_identifiers = {"birth_year", "city", "occupation"}
sensitive_fields = {"monthly_spend", "health_flag"}

inventory = []
for col in customers.columns:
    if col in direct_identifiers:
        risk_type = "直接識別風險"
        sensitivity = "個人資料"
        suggested_action = "遮蔽或雜湊"
    elif col in quasi_identifiers:
        risk_type = "間接識別風險"
        sensitivity = "準識別資訊"
        suggested_action = "泛化並檢查再識別風險"
    elif col in sensitive_fields:
        risk_type = "敏感資料風險"
        sensitivity = "高度敏感或機密資料"
        suggested_action = "限制存取並最小化使用"
    else:
        risk_type = "低風險"
        sensitivity = "一般資料"
        suggested_action = "定期監控"

    inventory.append({
        "欄位": col,
        "風險類型": risk_type,
        "敏感度層級": sensitivity,
        "建議處理方式": suggested_action
    })

inventory_df = pd.DataFrame(inventory)
display(inventory_df)
